function aiAnswer0(q) { const s = q.toLowerCase(); const L = (a, b) => `<a href="#${b}">${esc(a)}</a>`;
  if (/approval|persetujuan|موافق/.test(s)) { const o = APPROVALS.filter(a => ['waiting', 'in_progress'].includes(a.status)); return `${o.length} approval ${L3(['terbuka', 'open', 'مفتوحة'])}, ${o.filter(a => a.priority === 'p1').length} ${L3(['prioritas tinggi', 'high priority', 'عالية'])}. ${L3(['Risiko tertinggi', 'Highest risk', 'الأعلى خطورة'])}: ${L(o.sort((a, b) => b.risk - a.risk)[0].title, '/approval/' + o[0].id)} (risk ${o[0].risk}).`; }
  if (/izin|legal|ppiu|pihk|bpw|expired/.test(s)) { const ex = TRAVELS.filter(x => ['expired', 'expiring', 'rejected'].includes(x.legal)); return `${ex.length} Travel ${L3(['dengan legalitas bermasalah', 'with legality issues', 'بمشكلات ترخيص'])}: ${ex.slice(0, 4).map(x => L(x.name + ' (' + L3(STATUS[x.legal].slice(2)) + ')', '/travel/' + x.id + '/legal')).join(', ')}${ex.length > 4 ? '…' : ''}. ${L('Legalitas & Perizinan', '/travel/legal')}`; }
  if (/campaign|roas|iklan|ads/.test(s)) { const c = CAMPAIGNS.filter(x => x.spent).sort((a, b) => campRoas(b) - campRoas(a)); return `ROAS ${L3(['tertinggi', 'highest', 'الأعلى'])}: ${L(c[0].name, '/ads/campaign/' + c[0].id)} (${fN(campRoas(c[0]), { maximumFractionDigits: 1 })}×). ${L3(['Terendah', 'Lowest', 'الأدنى'])}: ${L(c[c.length - 1].name, '/ads/campaign/' + c[c.length - 1].id)} (${fN(campRoas(c[c.length - 1]), { maximumFractionDigits: 1 })}×).`; }
  if (/settle|withdraw|refund|rekonsil|recon|keuangan|finance/.test(s)) return `Settlement: ${SETTLEMENTS.filter(x => x.state === 'failed').length} failed, ${SETTLEMENTS.filter(x => x.state === 'hold').length} hold. Withdrawal pending: ${WITHDRAWALS.filter(w => w.state === 'pending').length} (${money(WITHDRAWALS.filter(w => w.state === 'pending').reduce((s, w) => s + w.amount, 0))}). Unmatched: ${PAYMENTS.filter(p => ['unmatched', 'mismatch'].includes(p.recon)).length}. ${L('Finance Overview', '/finance')} · ${L('Reconciliation', '/finance/reconciliation')}`;
  if (/sla|inbox|percakapan|chat|pesan/.test(s)) return `${CONVERSATIONS.filter(c => c.status === 'open').length} open, ${CONVERSATIONS.filter(c => !c.assignee && ['open', 'pending'].includes(c.status)).length} unassigned, ${CONVERSATIONS.filter(c => c.sla != null && c.sla < 0).length} SLA breach. ${L('Inbox', '/omni/inbox')}`;
  const tr = TRAVELS.find(x => s.includes(x.name.toLowerCase().split(' ')[0].toLowerCase()) || s.includes(x.id.toLowerCase())); if (tr) return `${L(tr.name, '/travel/' + tr.id)} · ${L3(STATUS[tr.op === 'review' ? 'review' : tr.op].slice(2))} · legal ${L3(STATUS[tr.legal].slice(2))} · ${tr.sub.plan} (${L3(STATUS[tr.sub.state].slice(2))}) · GMV 30d ${money(tr.gmv30)} · ${tr.payMode}.`;
  return L3(['Saya bisa merangkum: approval, legalitas/izin, campaign & ROAS, settlement/withdrawal/refund, Inbox & SLA, atau Travel tertentu (sebut nama/ID).', 'I can summarize: approvals, legality/licences, campaigns & ROAS, settlement/withdrawal/refund, Inbox & SLA, or a specific Travel (name/ID).', 'يمكنني تلخيص: الموافقات، التراخيص، الحملات، المالية، صندوق الوارد.']); }
